import {readFileSync, writeFileSync, mkdirSync} from 'node:fs';
import {parseContract} from '../src/base/seed-contract.mjs';

// Keep derived acceptance and claim documents tied to the installed parser.
// This edition helper does not refresh the pinned Base source.
const command = process.argv[2];
if (!['write', 'check'].includes(command)) throw Error('Use write or check');
const source = readFileSync('CONTRACT.md', 'utf8');
const contract = parseContract(source);
const lines = source.split('\n');
const outputs = new Map();
const acceptance = [
  '# First release', '',
  '<!-- Generated by node scripts/contract-docs.mjs write from CONTRACT.md. -->', '',
  'The acceptance journeys and implementation evidence below come from [CONTRACT.md](CONTRACT.md). Its complete clause text remains authoritative. Status describes current implementation, not a reduced target.', '',
];
let area;
for (const clause of contract.clauses) {
  if (clause.area !== area) {
    area = clause.area;
    acceptance.push('## ' + area, '');
  }
  const marker = '**Acceptance evidence:**';
  const index = clause.text.indexOf(marker);
  if (index < 0) throw Error(clause.id + ' has no acceptance evidence');
  const row = lines[clause.row - 1].split(/(?<!\\)\|/).slice(1, -1).map(value => value.trim());
  const evidence = row[4], gap = row[5];
  acceptance.push(`- **${clause.id} — ${clause.title}. Status: ${clause.status}.** ${clause.text.slice(index + marker.length).trim()}`,
    `  Current evidence: ${evidence}${gap ? ' Remaining: ' + gap : ''}`, '');
}
outputs.set('ACCEPTANCE.md', acceptance.join('\n'));
const claims = /^## Homepage claims\n([\s\S]*?)(?=^## Status\n)/m.exec(source);
if (!claims) throw Error('The contract has no homepage claim register');
outputs.set('docs/CLAIMS.md', '# Homepage claims\n\n<!-- Generated by node scripts/contract-docs.mjs write from CONTRACT.md. -->\n' + claims[1]);
for (const [path, expected] of outputs) {
  // Preserve rendered prose while avoiding ambiguous repository shorthand.
  const rendered = expected.replace(/(?<![\w./:@-])([A-Za-z][\w-]*)\/([A-Za-z][\w-]*)(?![\w./-])/g, '$1&#47;$2').trimEnd() + '\n';
  if (command === 'write') {
    if (path.startsWith('docs/')) mkdirSync('docs', {recursive: true});
    writeFileSync(path, rendered);
  } else if (readFileSync(path, 'utf8') !== rendered) throw Error(path + ' is stale; run node scripts/contract-docs.mjs write');
}
console.log(`Contract documents ${command === 'write' ? 'regenerated' : 'match'}: ${contract.counts.total} clauses; ${contract.counts.done} done, ${contract.counts.partial} partial, ${contract.counts.missing} missing.`);
